-- WhyTheyNameThisWay: extra words found in WoW Forever names (NPCs, items, objects, places).
-- W(level, key, meaning, roots, example). level: 1 Basic, 2 Intermediate, 3 Advanced.
-- Entries already in Data.lua win; Levels.lua lists win over the level given here.
local ADDON, ns = ...
local D, L = ns.D, ns.LEVEL
local function W(level, key, meaning, roots, example)
    if not meaning or meaning == "" or D[key] then return end
    D[key] = { meaning, roots, example }
    if level < 3 and L[key] == nil then L[key] = level end
end

