W(3, "windshear mine", "A mine is a hole dug to take out metal. Wind shear is a sudden change in wind direction.", "shear: to cut, like with big scissors", "The farmer shears his sheep in spring.")
W(3, "winterfall village", "A village is a small group of homes. The Winterfall furbolgs live here in snowy Winterspring.", "", "Winter came early this year.")
W(3, "winterhoof water well", "A well is a deep hole for getting water. Winterhoof is a tauren family name; a hoof is an animal's hard foot.", "", "The horse hurt its hoof.")
W(3, "wizard's sanctum", "A sanctum is a private, holy room. This is a quiet place where wizards study magic.", "sanctum: from Latin 'sanctus', holy", "His office was his private sanctum.")
